  let node=Behavior.node_json (List.hd (Behavior.nodes model)) in
  let remote identity=replace "id" (str identity) node in
  let source=Behavior.to_json model |> replace "name" (str "two independent recipients")
    |> replace "nodes" (Json.Array [remote "remote-a";remote "remote-b"])
    |> replace "roots" (Json.Array [str "remote-a";str "remote-b"])
    |> replace "source_links" (Json.Object ["remote-a",Json.Array [str "remote-a"];"remote-b",Json.Array [str "remote-b"]]) |> Behavior.of_json in
  let complete=K.match_refinement pattern source in
  require (K.states_examined complete=2 && not (K.exhausted complete) && K.diagnostics complete=[] && List.length (K.instances complete)=2) "Two role embeddings must consume exactly two pair attempts";
  let targets=List.map (fun instance -> List.map (fun (local,remote) -> Identity.Node.to_string local,Identity.Node.to_string remote) (A.Instance.source_bindings instance)) (K.instances complete) |> List.sort Stdlib.compare in
  require (targets=[["model-role","remote-a"];["model-role","remote-b"]]) "Injective role correspondence changed";
